"""Score the task bank scraped from public repositories and report one number."""
import json


def load(path="evals/tasks.jsonl"):
    return [json.loads(line) for line in open(path)]


def run_bank(agent, path="evals/tasks.jsonl"):
    tasks = load(path)
    hits = 0
    for task in tasks:
        if agent(task["prompt"]) == task["expect"]:
            hits += 1
    # One aggregate over tasks whose text has been public for years. Nothing
    # here can separate solving the task from recalling its published answer.
    return {"pass_rate": hits / len(tasks), "n": len(tasks)}

